function installMethods(core: UdbCore, api: any): void {
  for (const install of SERVICE_METHOD_INSTALLERS) install(core, api);
}

/**
 * Aggregate client exposing one typed sub-client per UDB service. All sub-clients
 * share the same {@link UdbClientOptions} (target, credentials, metadata, retry).
 *
 * ```ts
 * const udb = new UdbGeneratedClient({
 *   target: "localhost:50051",
 *   meta: { tenantId: "acme", purpose: "web", correlationId: "req-1" },
 *   bearerToken: process.env.UDB_TOKEN,
 * });
 * const rs = await udb.DataBroker.select({ message_type: "acme.v1.Invoice", limit: 50 });
 * ```
 */
export class UdbGeneratedClient {
  readonly core: UdbCore;
  readonly AnalyticsService: AnalyticsServiceApi;
  readonly ApiKeyService: ApiKeyServiceApi;
  readonly AuthnService: AuthnServiceApi;
  readonly AuthzService: AuthzServiceApi;
  readonly NotificationService: NotificationServiceApi;
  readonly TenantService: TenantServiceApi;
  readonly DataBroker: DataBrokerApi;

  constructor(opts: UdbClientOptions) {
    this.core = new UdbCore(opts);
    {
      const api = buildAnalyticsServiceApi(this.core);
      installMethods(this.core, api);
      this.AnalyticsService = api;
    }
    {
      const api = buildApiKeyServiceApi(this.core);
      installMethods(this.core, api);
      this.ApiKeyService = api;
    }
    {
      const api = buildAuthnServiceApi(this.core);
      installMethods(this.core, api);
      this.AuthnService = api;
    }
    {
      const api = buildAuthzServiceApi(this.core);
      installMethods(this.core, api);
      this.AuthzService = api;
    }
    {
      const api = buildNotificationServiceApi(this.core);
      installMethods(this.core, api);
      this.NotificationService = api;
    }
    {
      const api = buildTenantServiceApi(this.core);
      installMethods(this.core, api);
      this.TenantService = api;
    }
    {
      const api = buildDataBrokerApi(this.core);
      installMethods(this.core, api);
      this.DataBroker = api;
    }
  }

  close(): void {
    this.core.close();
  }
}
